package org.example.requests.infrastructure.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.SequenceGenerator;
import jakarta.persistence.Table;

import java.time.Instant;

/**
 * Record of an issued publication number. The number is the id, generated by Hibernate from a database
 * sequence (or a table on databases without sequences), so no database-specific SQL is needed.
 */
@Entity
@Table(name = "publication_numbers")
class PublicationNumberEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "publication_number_gen")
    @SequenceGenerator(name = "publication_number_gen", sequenceName = "publication_number_seq", allocationSize = 1)
    Long number;

    @Column(nullable = false)
    Instant issuedAt = Instant.now();
}
